-- CRM Ana — Fase 3: importação da base inicial (4 palestras / Sympla)
-- 1.128 leads únicos. Cole no SQL Editor do Supabase e clique Run.
-- Idempotente por e-mail (on conflict do nothing).
-- =====================================================================

-- 1) Origens (uma por palestra)
on conflict do nothing;

-- 2) Leads
on conflict (email_normalizado) do nothing;

-- 3) Trilha de consentimento (LGPD) para os leads importados
select id,'opt_in','email','consentimento',
       'Inscrição em palestra (Sympla) — importação da base inicial', null
from leads
where origem_id in ('c3c546fa-7e75-46d4-9cc9-d1c8b68f94c6', 'a41f4b7b-231f-4280-a529-a9655a3c830d', 'ce277171-eccb-4462-b0fa-e4461ce1f26b', '9f0242ba-b310-4cad-a43c-a0cb7e34c6c5');

-- FIM — base importada. Confira no painel: Visão geral deve acender.